import sys
from math import gcd

def min_operations_to_one(n, a):
    if 1 in a:
        return n - a.count(1)

    min_val = min(a)
    if min_val > 1:
        return -1

    total_operations = 0
    for i in range(n):
        if a[i] == 1:
            continue
        for j in range(i + 1, n):
            if gcd(a[i], a[j]) == 1:
                total_operations += j - i - 1
                break
        else:
            return -1

    return total_operations

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = list(map(int, data[1:]))

    result = min_operations_to_one(n, a)
    print(result)

if __name__ == "__main__":
    main()
